def is_lucky_digit(digit):
    return digit == 4 or digit == 7

def is_nearly_lucky_number(n):
    lucky_digit_count = 0

    # Count the lucky digits (4 and 7) in the number
    while n > 0:
        digit = n % 10
        if is_lucky_digit(digit):
            lucky_digit_count += 1
        n //= 10

    # Check if the count of lucky digits is itself a lucky number (only 4 or 7)
    return lucky_digit_count == 4 or lucky_digit_count == 7

if __name__ == "__main__":
