def is_almost_lucky_number(n):
    n_str = str(n)
    count = 0
    for digit in n_str:
        if digit == '4' or digit == '7':
            count += 1
    count_str = str(count)
    for digit in count_str:
        if digit != '4' and digit != '7':
            return "NO"
    return "YES"

